package com.collabcase.project.version;
import org.springframework.boot.ApplicationArguments;import org.springframework.boot.ApplicationRunner;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import com.collabcase.diagram.DiagramRepository;import com.collabcase.project.ProjectRepository;
@Component public class ProjectVersionMigration implements ApplicationRunner{private final ProjectRepository projects;private final ProjectVersionService service;private final DiagramRepository diagrams;public ProjectVersionMigration(ProjectRepository projects,ProjectVersionService service,DiagramRepository diagrams){this.projects=projects;this.service=service;this.diagrams=diagrams;}@Override @Transactional public void run(ApplicationArguments args){for(var project:projects.findAll()){var main=service.ensureMain(project);for(var diagram:diagrams.findByProjectIdOrderByUpdatedAtDesc(project.getId()))if(diagram.getVersion()==null){diagram.setVersion(main);diagrams.save(diagram);}}}}
